tool_input.new_string:
@pytest.mark.parametrize(
    "value",
    [
        pytest.param(_UNKNOWN_MODE, id="unknown-string"),
        pytest.param(None, id="missing"),
        pytest.param(3, id="wrong-type"),
    ],
)
def test_parse_content_mode_rejects_unknown_values(value: object) -> None:
    """An unrecognized mode falls back to the caller's default."""
    assert parse_content_mode(value, SNAPSHOT_CONTENT_MODE) == SNAPSHOT_CONTENT_MODE, (
        f"{value!r} is not a known mode and must fall back to the default"
    )


@given(value=strategies.text(max_size=32), default=strategies.sampled_from((DEFAULT_CONTENT_MODE, SNAPSHOT_CONTENT_MODE)))
def test_parse_content_mode_always_returns_a_known_mode(
    value: str,
    default: str,
) -> None:
    """Parsing any text yields a declared mode, never the raw input."""
    parsed = parse_content_mode(value, cast("ContentMode", default))

    assert parsed in (DEFAULT_CONTENT_MODE, SNAPSHOT_CONTENT_MODE), (
        f"parsing {value!r} must yield a declared mode, got {parsed!r}"
    )

